FUNCTION_BLOCK FB_Geothermal_BinaryORC_BrineSilica
(*
========================================================================================================
CYBER-PHYSICAL ADVANCED AUTOMATION ARCHITECTURE FOR GEOTHERMAL BINARY POWER PLANTS
Subsystem: Dual-Pressure Organic Rankine Cycle (ORC) Isobutane Vaporizers & Brine Anti-Silica Mitigation
Safety Integrity Level: SIL-3 Architectural Design / TMR 2oo3 Redundant Voting
Mathematical Framework: Discrete State-Space Model Predictive Controller (MPC) with LQR State-Feedback,
                        Fournier & Rowe Amorphous Silica Precipitation Kinetics, and ISA-18.2 Alarm Topology.

Operational Scope:
1. Manages high-pressure (HP) and low-pressure (LP) isobutane (i-C4H10 / R-600a) shell-and-tube vaporizers
   coupled with geothermal brine shell-and-tube heat exchangers.
2. Prevents irreversible amorphous silica (SiO2) scaling in downstream piping, heat exchanger bundles,
   and reinjection wells by actively computing the Silica Saturation Index (SSI) and controlling brine
   reinjection temperature, brine bypass bypass flow, and stoichiometry-matched acid/inhibitor chemical injection.
3. Implements 2oo3 Triple Modular Redundancy (TMR) voting with automatic sensor degradation (2oo3 -> 1oo2 -> Fail-Safe).
4. Executes a 4-state, 3-input discrete state-space LQR formulation with integral action and anti-windup clamping.
========================================================================================================
*)

VAR_INPUT
    bEnable                         : BOOL;     (* System master operational permissive [TRUE = Active, FALSE = Controlled Shutdown] *)
    bEmergencyStop                  : BOOL;     (* Hardwired SIL-3 emergency trip line (Active Low, FALSE = Immediate Trip) *)
    bAcknowledgeFault               : BOOL;     (* Operator manual alarm and trip latch reset pulse *)
    bTurbineTripped                 : BOOL;     (* Binary ORC turbo-expander trip status [TRUE = Tripped, engages fast bypass] *)

    (* Primary Geothermal Brine Process Inputs *)
    rBrineInletPress_bar            : REAL;     (* Wellhead geothermal brine supply pressure [bar] *)
    rBrineInletTemp_degC_A          : REAL;     (* Wellhead geothermal brine supply temperature Channel A [deg C] *)
    rBrineInletTemp_degC_B          : REAL;     (* Wellhead geothermal brine supply temperature Channel B [deg C] *)
    rBrineInletTemp_degC_C          : REAL;     (* Wellhead geothermal brine supply temperature Channel C [deg C] *)
    rBrineMassFlow_kgs              : REAL;     (* Total geothermal brine mass flow entering vaporizers [kg/s] *)
    rBrineSilicaConc_ppm            : REAL;     (* Real-time quartz/molybdate online dissolved SiO2 analyzer [ppm] *)

    (* Brine Reinjection Header Monitoring (TMR 2oo3) *)
    rBrineReinjTemp_degC_A          : REAL;     (* Reinjection header temperature sensor Channel A [deg C] *)
    rBrineReinjTemp_degC_B          : REAL;     (* Reinjection header temperature sensor Channel B [deg C] *)
    rBrineReinjTemp_degC_C          : REAL;     (* Reinjection header temperature sensor Channel C [deg C] *)
    rBrineReinjPH_A                 : REAL;     (* Reinjection header glass-electrode pH analyzer Channel A [pH] *)
    rBrineReinjPH_B                 : REAL;     (* Reinjection header glass-electrode pH analyzer Channel B [pH] *)
    rBrineReinjPH_C                 : REAL;     (* Reinjection header glass-electrode pH analyzer Channel C [pH] *)

    (* Dual-Pressure Isobutane Vaporizer Pressure Instruments (TMR 2oo3) *)
    rHPVapPress_bar_A               : REAL;     (* High-pressure vaporizer shell pressure transmitter Channel A [bar] *)
    rHPVapPress_bar_B               : REAL;     (* High-pressure vaporizer shell pressure transmitter Channel B [bar] *)
    rHPVapPress_bar_C               : REAL;     (* High-pressure vaporizer shell pressure transmitter Channel C [bar] *)
    rLPVapPress_bar_A               : REAL;     (* Low-pressure vaporizer shell pressure transmitter Channel A [bar] *)
    rLPVapPress_bar_B               : REAL;     (* Low-pressure vaporizer shell pressure transmitter Channel B [bar] *)
    rLPVapPress_bar_C               : REAL;     (* Low-pressure vaporizer shell pressure transmitter Channel C [bar] *)

    (* Auxiliary Plant Variables *)
    rAcidStorageTankLevel_pct       : REAL;     (* Anti-silica acid/inhibitor day-tank inventory [0.0..100.0 %] *)
    rCycleTime_s                    : REAL;     (* Execution loop delta time interval [s] (Nominal: 0.050 s) *)
END_VAR

VAR_OUTPUT
    rValveDemand_HPVap_pct          : REAL;     (* HP isobutane turbine admission / bypass control valve command [0.0..100.0 %] *)
    rValveDemand_LPVap_pct          : REAL;     (* LP isobutane turbine admission / bypass control valve command [0.0..100.0 %] *)
    rValveDemand_BrineBypass_pct    : REAL;     (* Brine heat exchanger thermal bypass 3-way valve command [0.0..100.0 %] *)
    rPumpDemand_AcidDose_lph        : REAL;     (* Anti-silica chemical metering dosing pump stroke/speed command [l/h] *)
    rSilicaSaturationIndex          : REAL;     (* Calculated amorphous silica saturation index (SSI = C_actual / C_solubility) [-] *)
    rReinjectionTemp_degC           : REAL;     (* 2oo3 validated geothermal brine reinjection temperature [deg C] *)
    rHPVapPress_Voted_bar           : REAL;     (* 2oo3 validated HP isobutane vaporizer shell pressure [bar] *)
    rLPVapPress_Voted_bar           : REAL;     (* 2oo3 validated LP isobutane vaporizer shell pressure [bar] *)
    rBrineReinjPH_Voted             : REAL;     (* 2oo3 validated geothermal brine reinjection pH [pH] *)
    wDiagnosticStatusWord           : WORD;     (* Subsystem operational and architectural bitfield status *)
    dwAlarmBitmask                  : DWORD;    (* ISA-18.2 compliant prioritized alarm annunciator bitmask *)
    bSafetyTripActive               : BOOL;     (* Master safety trip relay command [TRUE = Tripped, valves fail-safe] *)
    bDegradedSensorMode             : BOOL;     (* Fault-tolerant operation flag: one or more TMR channels degraded *)
    bSystemReady                    : BOOL;     (* Subsystem permissive confirmed: Ready for full dual-pressure power extraction *)
END_VAR

VAR
    (* Finite State Machine Operational Registers *)
    iState                          : INT := 0; (* Internal execution state index [0..90] *)
    iPreviousState                  : INT := 0; (* State history tracer for transition debouncing *)
    tStateTimer                     : TON;      (* In-state dwell and timeout accumulation timer *)
    tDiscrepancyReinjTemp           : TON;      (* Reinjection temperature TMR channel disagreement timer *)
    tDiscrepancyHPVapPress          : TON;      (* HP vaporizer pressure TMR channel disagreement timer *)
    tDiscrepancyLPVapPress          : TON;      (* LP vaporizer pressure TMR channel disagreement timer *)
    tDiscrepancyPH                  : TON;      (* Brine reinjection pH TMR channel disagreement timer *)
    tAcidPumpInterlock              : TON;      (* Acid dosing pump dry-run lockout timer *)

    (* TMR Sensor Channel Validity and Health Bitfields *)
    bValid_BrineTemp_A              : BOOL := TRUE;
    bValid_BrineTemp_B              : BOOL := TRUE;
    bValid_BrineTemp_C              : BOOL := TRUE;
    bValid_HPVap_A                  : BOOL := TRUE;
    bValid_HPVap_B                  : BOOL := TRUE;
    bValid_HPVap_C                  : BOOL := TRUE;
    bValid_LPVap_A                  : BOOL := TRUE;
    bValid_LPVap_B                  : BOOL := TRUE;
    bValid_LPVap_C                  : BOOL := TRUE;
    bValid_PH_A                     : BOOL := TRUE;
    bValid_PH_B                     : BOOL := TRUE;
    bValid_PH_C                     : BOOL := TRUE;

    (* Amorphous Silica Thermodynamic Equilibrium Calculation Variables *)
    rKelvinTemp                     : REAL;     (* Absolute reinjection brine temperature [K] *)
    rLog10Solubility                : REAL;     (* Base-10 logarithm of neutral amorphous silica solubility *)
    rSilicaSolNeutral_ppm           : REAL;     (* Un-ionized amorphous silica solubility at local T [ppm SiO2] *)
    rPKa1_SilicicAcid               : REAL;     (* First dissociation constant of monosilicic acid (H4SiO4) *)
    rAlphaIonization                : REAL;     (* Ionization dissociation expansion ratio (pH enhancement factor) *)
    rSilicaSolEffective_ppm         : REAL;     (* Total effective silica solubility accounting for pH dissociation [ppm] *)
    rAcidStoichiometricGain         : REAL := 0.085; (* Base dosing factor in (l/h) per (kg/s brine * ppm excess SiO2) *)

    (* Model Predictive Control (MPC) / Discrete LQR State-Space Variables *)
    (* System States: x = [e_PHP, e_PLP, e_TReinj, e_SSI]^T *)
    (* Control Inputs: u = [u_HPVapValve, u_LPVapValve, u_BrineBypassValve]^T *)
    aState_x                        : ARRAY[1..4] OF REAL; (* State error vector *)
    aStateIntegral                  : ARRAY[1..4] OF REAL; (* Augmented integral state vector for zero steady-state offset *)
    aControl_u                      : ARRAY[1..3] OF REAL; (* Raw unconstrained control output vector *)
    aControl_u_prev                 : ARRAY[1..3] OF REAL; (* Output vector from prior scan cycle for slew limiting *)

    (* Discrete State Space Matrix A (4x4) - Plant Dynamic Drift under Ts = 50ms *)
    aA_Matrix                       : ARRAY[1..4, 1..4] OF REAL := [
        0.9820, 0.0050, 0.0010, 0.0000,
        0.0030, 0.9780, 0.0020, 0.0000,
        0.0080, 0.0120, 0.9650, 0.0000,
        0.0000, 0.0000, -0.0140, 0.9910
    ];

    (* Input Gain Matrix B (4x3) - Actuator Couplings *)
    aB_Matrix                       : ARRAY[1..4, 1..3] OF REAL := [
        -0.0450,  0.0020,  0.0120,
         0.0010, -0.0520,  0.0180,
         0.0150,  0.0220,  0.0850,
        -0.0020, -0.0040, -0.0380
    ];

    (* Optimal LQR State-Feedback Gain Matrix K (3x4) Derived via Algebraic Riccati Solver *)
    (* Minimizes cost function: J = Sum(x^T Q x + u^T R u + Delta_u^T S Delta_u) *)
    aK_Gain                         : ARRAY[1..3, 1..4] OF REAL := [
        2.4500,  0.1200, -0.3500,  0.0800,
        0.0900,  2.8200, -0.4200,  0.1100,
        0.5500,  0.6800,  3.1500, -4.8500
    ];

    (* Setpoints, Safety Thresholds, and Engineering Limit Envelopes *)
    rSP_HPVapPress_bar              : REAL := 32.50; (* Target HP Isobutane Vaporizer Pressure [bar] *)
    rSP_LPVapPress_bar              : REAL := 13.80; (* Target LP Isobutane Vaporizer Pressure [bar] *)
    rTarget_MaxSSI                  : REAL := 1.05;  (* Upper setpoint target for Silica Saturation Index [-] *)
    rCritical_SSI_Threshold         : REAL := 1.25;  (* Immediate scale formation danger threshold [-] *)
    rSafetyFloor_ReinjTemp_degC     : REAL := 76.00; (* Absolute lowest allowable brine reinjection temp [deg C] *)
    rHigh_HPVapPress_Trip_bar       : REAL := 37.00; (* High-High HP Vaporizer Shell Pressure Safety Trip [bar] *)
    rHigh_LPVapPress_Trip_bar       : REAL := 17.50; (* High-High LP Vaporizer Shell Pressure Safety Trip [bar] *)
    rLow_BrineFlow_Trip_kgs         : REAL := 15.00; (* Low brine flow interlock threshold [kg/s] *)

    (* Filter Accumulators & Rate Limiters *)
    rFilt_HPVapPress                : REAL := 32.50;
    rFilt_LPVapPress                : REAL := 13.80;
    rFilt_ReinjTemp                 : REAL := 80.00;
    rFilt_ReinjPH                   : REAL := 6.50;
    rMaxSlewRate_pct_s              : REAL := 8.00;  (* Maximum actuator stroke velocity [percent/sec] to avoid surges *)

    (* Internal Computation Registers *)
    rDiffAB                         : REAL;
    rDiffBC                         : REAL;
    rDiffCA                         : REAL;
    rMedian                         : REAL;
    rExcessSilica_ppm               : REAL;
    rCalculatedAcidDemand           : REAL;
    rSlewCap                        : REAL;
    iRow                            : INT;
    iCol                            : INT;
END_VAR

(*
========================================================================================================
ALGORITHM SECTION 1: SIL-3 HARDWIRED EMERGENCY STOP & TRIP LATCH INTEGRITY
========================================================================================================
*)
IF NOT bEmergencyStop THEN
    bSafetyTripActive := TRUE;
    bSystemReady := FALSE;
    iState := 80; (* Force direct transition to EMERGENCY SHUTDOWN BRINE DUMP *)
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000001; (* Bit 0: Emergency Stop Asserted *)
END_IF;

(* Operator Fault Reset Pulse Evaluation *)
IF bAcknowledgeFault AND (iState = 90) AND bEmergencyStop THEN
    dwAlarmBitmask := 16#00000000;
    bSafetyTripActive := FALSE;
    iState := 0; (* Reset to Uninitialized Cold Standby *)
END_IF;

(*
========================================================================================================
ALGORITHM SECTION 2: 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING & SENSOR HEALTH DEGRADATION
========================================================================================================
*)

(* --- 2.1 Reinjection Temperature TMR Voting (Tolerance: 3.0 deg C) --- *)
rDiffAB := ABS(rBrineReinjTemp_degC_A - rBrineReinjTemp_degC_B);
rDiffBC := ABS(rBrineReinjTemp_degC_B - rBrineReinjTemp_degC_C);
rDiffCA := ABS(rBrineReinjTemp_degC_C - rBrineReinjTemp_degC_A);

tDiscrepancyReinjTemp(IN := (rDiffAB > 3.0) OR (rDiffBC > 3.0) OR (rDiffCA > 3.0), PT := T#2S);

IF tDiscrepancyReinjTemp.Q THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000010; (* Bit 4: TMR Temp Discrepancy *)
    bDegradedSensorMode := TRUE;
    (* Identify failed sensor deviating from majority *)
    IF (rDiffAB > 3.0) AND (rDiffCA > 3.0) THEN
        bValid_BrineTemp_A := FALSE;
        rReinjectionTemp_degC := (rBrineReinjTemp_degC_B + rBrineReinjTemp_degC_C) * 0.5;
    ELSIF (rDiffAB > 3.0) AND (rDiffBC > 3.0) THEN
        bValid_BrineTemp_B := FALSE;
        rReinjectionTemp_degC := (rBrineReinjTemp_degC_A + rBrineReinjTemp_degC_C) * 0.5;
    ELSIF (rDiffBC > 3.0) AND (rDiffCA > 3.0) THEN
        bValid_BrineTemp_C := FALSE;
        rReinjectionTemp_degC := (rBrineReinjTemp_degC_A + rBrineReinjTemp_degC_B) * 0.5;
    ELSE
        (* Total TMR collapse: Select conservative minimum to prevent freezing/scaling *)
        rReinjectionTemp_degC := MIN(rBrineReinjTemp_degC_A, MIN(rBrineReinjTemp_degC_B, rBrineReinjTemp_degC_C));
    END_IF;
ELSE
    bValid_BrineTemp_A := TRUE;
    bValid_BrineTemp_B := TRUE;
    bValid_BrineTemp_C := TRUE;
    (* Standard 2oo3 Median Selection *)
    IF ((rBrineReinjTemp_degC_A >= rBrineReinjTemp_degC_B) AND (rBrineReinjTemp_degC_A <= rBrineReinjTemp_degC_C)) OR
       ((rBrineReinjTemp_degC_A <= rBrineReinjTemp_degC_B) AND (rBrineReinjTemp_degC_A >= rBrineReinjTemp_degC_C)) THEN
        rReinjectionTemp_degC := rBrineReinjTemp_degC_A;
    ELSIF ((rBrineReinjTemp_degC_B >= rBrineReinjTemp_degC_A) AND (rBrineReinjTemp_degC_B <= rBrineReinjTemp_degC_C)) OR
          ((rBrineReinjTemp_degC_B <= rBrineReinjTemp_degC_A) AND (rBrineReinjTemp_degC_B >= rBrineReinjTemp_degC_C)) THEN
        rReinjectionTemp_degC := rBrineReinjTemp_degC_B;
    ELSE
        rReinjectionTemp_degC := rBrineReinjTemp_degC_C;
    END_IF;
END_IF;

(* --- 2.2 HP Vaporizer Pressure TMR Voting (Tolerance: 0.75 bar) --- *)
rDiffAB := ABS(rHPVapPress_bar_A - rHPVapPress_bar_B);
rDiffBC := ABS(rHPVapPress_bar_B - rHPVapPress_bar_C);
rDiffCA := ABS(rHPVapPress_bar_C - rHPVapPress_bar_A);

tDiscrepancyHPVapPress(IN := (rDiffAB > 0.75) OR (rDiffBC > 0.75) OR (rDiffCA > 0.75), PT := T#1500MS);

IF tDiscrepancyHPVapPress.Q THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000020; (* Bit 5: HP Press TMR Discrepancy *)
    bDegradedSensorMode := TRUE;
    IF (rDiffAB > 0.75) AND (rDiffCA > 0.75) THEN
        bValid_HPVap_A := FALSE;
        rHPVapPress_Voted_bar := (rHPVapPress_bar_B + rHPVapPress_bar_C) * 0.5;
    ELSIF (rDiffAB > 0.75) AND (rDiffBC > 0.75) THEN
        bValid_HPVap_B := FALSE;
        rHPVapPress_Voted_bar := (rHPVapPress_bar_A + rHPVapPress_bar_C) * 0.5;
    ELSIF (rDiffBC > 0.75) AND (rDiffCA > 0.75) THEN
        bValid_HPVap_C := FALSE;
        rHPVapPress_Voted_bar := (rHPVapPress_bar_A + rHPVapPress_bar_B) * 0.5;
    ELSE
        (* Conservative high selection for overpressure protection *)
        rHPVapPress_Voted_bar := MAX(rHPVapPress_bar_A, MAX(rHPVapPress_bar_B, rHPVapPress_bar_C));
    END_IF;
ELSE
    bValid_HPVap_A := TRUE;
    bValid_HPVap_B := TRUE;
    bValid_HPVap_C := TRUE;
    IF ((rHPVapPress_bar_A >= rHPVapPress_bar_B) AND (rHPVapPress_bar_A <= rHPVapPress_bar_C)) OR
       ((rHPVapPress_bar_A <= rHPVapPress_bar_B) AND (rHPVapPress_bar_A >= rHPVapPress_bar_C)) THEN
        rHPVapPress_Voted_bar := rHPVapPress_bar_A;
    ELSIF ((rHPVapPress_bar_B >= rHPVapPress_bar_A) AND (rHPVapPress_bar_B <= rHPVapPress_bar_C)) OR
          ((rHPVapPress_bar_B <= rHPVapPress_bar_A) AND (rHPVapPress_bar_B >= rHPVapPress_bar_C)) THEN
        rHPVapPress_Voted_bar := rHPVapPress_bar_B;
    ELSE
        rHPVapPress_Voted_bar := rHPVapPress_bar_C;
    END_IF;
END_IF;

(* --- 2.3 LP Vaporizer Pressure TMR Voting (Tolerance: 0.50 bar) --- *)
rDiffAB := ABS(rLPVapPress_bar_A - rLPVapPress_bar_B);
rDiffBC := ABS(rLPVapPress_bar_B - rLPVapPress_bar_C);
rDiffCA := ABS(rLPVapPress_bar_C - rLPVapPress_bar_A);

tDiscrepancyLPVapPress(IN := (rDiffAB > 0.50) OR (rDiffBC > 0.50) OR (rDiffCA > 0.50), PT := T#1500MS);

IF tDiscrepancyLPVapPress.Q THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000040; (* Bit 6: LP Press TMR Discrepancy *)
    bDegradedSensorMode := TRUE;
    IF (rDiffAB > 0.50) AND (rDiffCA > 0.50) THEN
        bValid_LPVap_A := FALSE;
        rLPVapPress_Voted_bar := (rLPVapPress_bar_B + rLPVapPress_bar_C) * 0.5;
    ELSIF (rDiffAB > 0.50) AND (rDiffBC > 0.50) THEN
        bValid_LPVap_B := FALSE;
        rLPVapPress_Voted_bar := (rLPVapPress_bar_A + rLPVapPress_bar_C) * 0.5;
    ELSIF (rDiffBC > 0.50) AND (rDiffCA > 0.50) THEN
        bValid_LPVap_C := FALSE;
        rLPVapPress_Voted_bar := (rLPVapPress_bar_A + rLPVapPress_bar_B) * 0.5;
    ELSE
        rLPVapPress_Voted_bar := MAX(rLPVapPress_bar_A, MAX(rLPVapPress_bar_B, rLPVapPress_bar_C));
    END_IF;
ELSE
    bValid_LPVap_A := TRUE;
    bValid_LPVap_B := TRUE;
    bValid_LPVap_C := TRUE;
    IF ((rLPVapPress_bar_A >= rLPVapPress_bar_B) AND (rLPVapPress_bar_A <= rLPVapPress_bar_C)) OR
       ((rLPVapPress_bar_A <= rLPVapPress_bar_B) AND (rLPVapPress_bar_A >= rLPVapPress_bar_C)) THEN
        rLPVapPress_Voted_bar := rLPVapPress_bar_A;
    ELSIF ((rLPVapPress_bar_B >= rLPVapPress_bar_A) AND (rLPVapPress_bar_B <= rLPVapPress_bar_C)) OR
          ((rLPVapPress_bar_B <= rLPVapPress_bar_A) AND (rLPVapPress_bar_B >= rLPVapPress_bar_C)) THEN
        rLPVapPress_Voted_bar := rLPVapPress_bar_B;
    ELSE
        rLPVapPress_Voted_bar := rLPVapPress_bar_C;
    END_IF;
END_IF;

(* --- 2.4 Brine Reinjection pH Analyzer TMR Voting (Tolerance: 0.40 pH) --- *)
rDiffAB := ABS(rBrineReinjPH_A - rBrineReinjPH_B);
rDiffBC := ABS(rBrineReinjPH_B - rBrineReinjPH_C);
rDiffCA := ABS(rBrineReinjPH_C - rBrineReinjPH_A);

tDiscrepancyPH(IN := (rDiffAB > 0.40) OR (rDiffBC > 0.40) OR (rDiffCA > 0.40), PT := T#3S);

IF tDiscrepancyPH.Q THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000080; (* Bit 7: pH TMR Discrepancy *)
    bDegradedSensorMode := TRUE;
    IF (rDiffAB > 0.40) AND (rDiffCA > 0.40) THEN
        bValid_PH_A := FALSE;
        rBrineReinjPH_Voted := (rBrineReinjPH_B + rBrineReinjPH_C) * 0.5;
    ELSIF (rDiffAB > 0.40) AND (rDiffBC > 0.40) THEN
        bValid_PH_B := FALSE;
        rBrineReinjPH_Voted := (rBrineReinjPH_A + rBrineReinjPH_C) * 0.5;
    ELSIF (rDiffBC > 0.40) AND (rDiffCA > 0.40) THEN
        bValid_PH_C := FALSE;
        rBrineReinjPH_Voted := (rBrineReinjPH_A + rBrineReinjPH_B) * 0.5;
    ELSE
        (* Acid dosing requires conservative low-pH detection to avoid over-acidification *)
        rBrineReinjPH_Voted := (rBrineReinjPH_A + rBrineReinjPH_B + rBrineReinjPH_C) / 3.0;
    END_IF;
ELSE
    bValid_PH_A := TRUE;
    bValid_PH_B := TRUE;
    bValid_PH_C := TRUE;
    IF ((rBrineReinjPH_A >= rBrineReinjPH_B) AND (rBrineReinjPH_A <= rBrineReinjPH_C)) OR
       ((rBrineReinjPH_A <= rBrineReinjPH_B) AND (rBrineReinjPH_A >= rBrineReinjPH_C)) THEN
        rBrineReinjPH_Voted := rBrineReinjPH_A;
    ELSIF ((rBrineReinjPH_B >= rBrineReinjPH_A) AND (rBrineReinjPH_B <= rBrineReinjPH_C)) OR
          ((rBrineReinjPH_B <= rBrineReinjPH_A) AND (rBrineReinjPH_B >= rBrineReinjPH_C)) THEN
        rBrineReinjPH_Voted := rBrineReinjPH_B;
    ELSE
        rBrineReinjPH_Voted := rBrineReinjPH_C;
    END_IF;
END_IF;

(* First-Order Exponential Lag Filtering on Voted Signals *)
rFilt_HPVapPress := rFilt_HPVapPress + 0.12 * (rHPVapPress_Voted_bar - rFilt_HPVapPress);
rFilt_LPVapPress := rFilt_LPVapPress + 0.12 * (rLPVapPress_Voted_bar - rFilt_LPVapPress);
rFilt_ReinjTemp  := rFilt_ReinjTemp  + 0.08 * (rReinjectionTemp_degC - rFilt_ReinjTemp);
rFilt_ReinjPH    := rFilt_ReinjPH    + 0.05 * (rBrineReinjPH_Voted - rFilt_ReinjPH);

(*
========================================================================================================
ALGORITHM SECTION 3: FOURNIER & ROWE AMORPHOUS SILICA SATURATION INDEX (SSI) ENGINE
========================================================================================================
*)
(* Convert reinjection temperature to absolute thermodynamic Kelvin *)
rKelvinTemp := rFilt_ReinjTemp + 273.15;
IF rKelvinTemp < 273.15 THEN
    rKelvinTemp := 273.15;
END_IF;

(* Neutral amorphous silica solubility via Fournier & Rowe (1977) empirical regression:
   log10(C_neutral [ppm]) = -731.0 / T[K] + 4.52 *)
rLog10Solubility := (-731.0 / rKelvinTemp) + 4.52;
rSilicaSolNeutral_ppm := EXPT(10.0, rLog10Solubility);

(* Monosilicic acid first dissociation constant (pK_a1) temperature dependency *)
rPKa1_SilicicAcid := 9.90 - (0.017 * rFilt_ReinjTemp);

(* Ionization enhancement factor: alpha = 1 + 10^(pH - pKa1) *)
rAlphaIonization := 1.0 + EXPT(10.0, (rFilt_ReinjPH - rPKa1_SilicicAcid));

(* Total effective silica solubility in geothermal brine environment *)
rSilicaSolEffective_ppm := rSilicaSolNeutral_ppm * rAlphaIonization;

(* Calculate dimensionless Silica Saturation Index (SSI) *)
IF rSilicaSolEffective_ppm > 1.0 THEN
    rSilicaSaturationIndex := rBrineSilicaConc_ppm / rSilicaSolEffective_ppm;
ELSE
    rSilicaSaturationIndex := 9.99;
END_IF;

(* Evaluate Immediate Silica Scaling Hazards *)
IF rSilicaSaturationIndex >= rCritical_SSI_Threshold THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000100; (* Bit 8: High-High Silica Scaling Risk *)
END_IF;

IF rFilt_ReinjTemp <= rSafetyFloor_ReinjTemp_degC THEN
    dwAlarmBitmask := dwAlarmBitmask OR 16#00000200; (* Bit 9: Reinjection Temp Critical Floor Violation *)
END_IF;

(*
========================================================================================================
ALGORITHM SECTION 4: DISCRETE STATE-SPACE MODEL PREDICTIVE CONTROLLER (LQR-MPC)
========================================================================================================
*)
(* State 1: HP Vaporizer Pressure Error (bar) *)
aState_x[1] := rFilt_HPVapPress - rSP_HPVapPress_bar;

(* State 2: LP Vaporizer Pressure Error (bar) *)
aState_x[2] := rFilt_LPVapPress - rSP_LPVapPress_bar;

(* State 3: Reinjection Temperature Margin Error (Positive when below safe thermal floor) *)
aState_x[3] := rSafetyFloor_ReinjTemp_degC - rFilt_ReinjTemp;

(* State 4: Silica Saturation Index Deviation (Positive when exceeding target SSI) *)
aState_x[4] := rSilicaSaturationIndex - rTarget_MaxSSI;

(* Accumulated Integral Action with Dynamic Anti-Windup Clamping *)
IF (iState = 40) OR (iState = 50) THEN
    aStateIntegral[1] := aStateIntegral[1] + (aState_x[1] * rCycleTime_s);
    aStateIntegral[2] := aStateIntegral[2] + (aState_x[2] * rCycleTime_s);
    aStateIntegral[3] := aStateIntegral[3] + (aState_x[3] * rCycleTime_s);
    aStateIntegral[4] := aStateIntegral[4] + (aState_x[4] * rCycleTime_s);

    (* Clamping integral states *)
    aStateIntegral[1] := LIMIT(-25.0, aStateIntegral[1], 25.0);
    aStateIntegral[2] := LIMIT(-25.0, aStateIntegral[2], 25.0);
    aStateIntegral[3] := LIMIT(0.0, aStateIntegral[3], 50.0);   (* Unidirectional anti-freeze integral *)
    aStateIntegral[4] := LIMIT(0.0, aStateIntegral[4], 30.0);   (* Unidirectional anti-scale integral *)
ELSE
    aStateIntegral[1] := 0.0;
    aStateIntegral[2] := 0.0;
    aStateIntegral[3] := 0.0;
    aStateIntegral[4] := 0.0;
END_IF;

(* Matrix Multiplication: Compute Optimal Control Feedback Moves u = -K*x - K_i*x_int *)
FOR iRow := 1 TO 3 DO
    aControl_u[iRow] := 0.0;
    FOR iCol := 1 TO 4 DO
        aControl_u[iRow] := aControl_u[iRow] - (aK_Gain[iRow, iCol] * aState_x[iCol]);
    END_FOR;
END_FOR;

(* Baseline Operating Points for Actuators *)
aControl_u[1] := aControl_u[1] + 55.0 - (0.40 * aStateIntegral[1]); (* Nominal HP Throttle Valve % *)
aControl_u[2] := aControl_u[2] + 48.0 - (0.45 * aStateIntegral[2]); (* Nominal LP Throttle Valve % *)
aControl_u[3] := aControl_u[3] + 12.0 + (0.85 * aStateIntegral[3]) + (1.20 * aStateIntegral[4]); (* Brine Bypass % *)

(*
========================================================================================================
ALGORITHM SECTION 5: MULTI-STAGE FINITE STATE MACHINE (ISA-88 HIERARCHY)
========================================================================================================
*)
tStateTimer(IN := (iState = iPreviousState), PT := T#24H);
iPreviousState := iState;

CASE iState OF

    0: (* UNINITIALIZED COLD STANDBY *)
        bSystemReady := FALSE;
        rValveDemand_HPVap_pct := 0.0;
        rValveDemand_LPVap_pct := 0.0;
        rValveDemand_BrineBypass_pct := 100.0; (* Full brine diversion away from cold ORC heat exchangers *)
        rPumpDemand_AcidDose_lph := 0.0;
        wDiagnosticStatusWord := 16#0001; (* Status: Standby *)

        IF bEnable AND bEmergencyStop AND (rBrineInletPress_bar > 5.0) AND (rBrineMassFlow_kgs > rLow_BrineFlow_Trip_kgs) THEN
            iState := 10;
        END_IF;

    10: (* SENSOR TMR INTEGRITY & AUXILIARY WARMUP VALIDATION *)
        wDiagnosticStatusWord := 16#0002; (* Status: Sensor Qualification *)
        rValveDemand_BrineBypass_pct := 100.0;

        (* Verify all 3 channels have responded without gross electrical faults *)
        IF (rBrineInletTemp_degC_A > 100.0) AND (rFilt_ReinjTemp > 20.0) AND (rAcidStorageTankLevel_pct > 15.0) THEN
            iState := 20;
        ELSIF tStateTimer.ET > T#30S THEN
            dwAlarmBitmask := dwAlarmBitmask OR 16#00000400; (* Bit 10: Sensor Warmup Timeout *)
            iState := 80;
        END_IF;

    20: (* BRINE HEAT EXCHANGER PRE-WARMUP & PRESSURE EQUALIZATION *)
        wDiagnosticStatusWord := 16#0004; (* Status: Brine Warmup *)
        (* Gradually introduce 15% geothermal brine flow to preheat vaporizer tube sheets *)
        rValveDemand_BrineBypass_pct := 85.0;
        rValveDemand_HPVap_pct := 5.0;
        rValveDemand_LPVap_pct := 5.0;

        (* Minimum thermal envelope threshold before boiling isobutane *)
        IF (rFilt_ReinjTemp > 65.0) AND (tStateTimer.ET > T#60S) THEN
            iState := 30;
        END_IF;

    30: (* DUAL-PRESSURE ORC VAPORIZER PRESSURIZATION RAMP *)
        wDiagnosticStatusWord := 16#0008; (* Status: Pressurization Ramp *)
        (* Slowly throttle brine bypass closed to transfer full heat to isobutane evaporator *)
        rValveDemand_BrineBypass_pct := LIMIT(10.0, 85.0 - (TIME_TO_REAL(tStateTimer.ET) / 1000.0 * 1.25), 85.0);
        rValveDemand_HPVap_pct := LIMIT(5.0, 5.0 + (TIME_TO_REAL(tStateTimer.ET) / 1000.0 * 0.8), 45.0);
        rValveDemand_LPVap_pct := LIMIT(5.0, 5.0 + (TIME_TO_REAL(tStateTimer.ET) / 1000.0 * 0.7), 40.0);

        IF (rFilt_HPVapPress >= (rSP_HPVapPress_bar - 3.0)) AND (rFilt_LPVapPress >= (rSP_LPVapPress_bar - 2.0)) THEN
            iState := 40;
        END_IF;

    40: (* NOMINAL DUAL-PRESSURE CLOSED-LOOP MPC OPERATION *)
        bSystemReady := TRUE;
        wDiagnosticStatusWord := 16#0010; (* Status: Nominal Closed-Loop *)

        (* Transfer calculated LQR-MPC control vectors to valve demands *)
        rValveDemand_HPVap_pct := aControl_u[1];
        rValveDemand_LPVap_pct := aControl_u[2];
        rValveDemand_BrineBypass_pct := aControl_u[3];

        (* Dynamic Stoichiometric Anti-Silica Acid / Dispersant Dosing *)
        IF rSilicaSaturationIndex > 0.95 THEN
            rExcessSilica_ppm := MAX(0.0, rBrineSilicaConc_ppm - rSilicaSolEffective_ppm);
            rCalculatedAcidDemand := rBrineMassFlow_kgs * rExcessSilica_ppm * rAcidStoichiometricGain * 0.01;
            rPumpDemand_AcidDose_lph := LIMIT(2.0, rCalculatedAcidDemand, 120.0);
        ELSE
            rPumpDemand_AcidDose_lph := 2.0; (* Minimum trickle dosing to prevent check valve clogging *)
        END_IF;

        (* Transitions to mitigation or trip *)
        IF bTurbineTripped THEN
            iState := 60; (* Engage Fast Vaporizer Bypass *)
        ELSIF (rSilicaSaturationIndex > rTarget_MaxSSI) OR (rFilt_ReinjTemp < (rSafetyFloor_ReinjTemp_degC + 2.0)) THEN
            iState := 50; (* High Silica Mitigation *)
        ELSIF (rFilt_HPVapPress > rHigh_HPVapPress_Trip_bar) OR (rFilt_LPVapPress > rHigh_LPVapPress_Trip_bar) THEN
            iState := 80; (* Critical Overpressure Trip *)
        END_IF;

    50: (* ELEVATED SILICA SCALING SUPPRESSION & BRINE BYPASS BOOST *)
        wDiagnosticStatusWord := 16#0020; (* Status: Silica Mitigation Mode *)
        dwAlarmBitmask := dwAlarmBitmask OR 16#00000800; (* Bit 11: Active Scale Mitigation *)

        (* Force brine bypass opening to elevate reinjection temperature and restore solubility *)
        rValveDemand_BrineBypass_pct := LIMIT(25.0, aControl_u[3] + 20.0, 90.0);

        (* Slightly de-rate ORC vaporizer heat extraction to protect well field *)
        rValveDemand_HPVap_pct := aControl_u[1] * 0.85;
        rValveDemand_LPVap_pct := aControl_u[2] * 0.85;

        (* Overdrive chemical acid/inhibitor dosing pump *)
        rExcessSilica_ppm := MAX(0.0, rBrineSilicaConc_ppm - rSilicaSolEffective_ppm);
        rPumpDemand_AcidDose_lph := LIMIT(15.0, (rBrineMassFlow_kgs * rExcessSilica_ppm * rAcidStoichiometricGain * 0.02) + 10.0, 150.0);

        (* Return condition *)
        IF (rSilicaSaturationIndex <= 0.98) AND (rFilt_ReinjTemp >= (rSafetyFloor_ReinjTemp_degC + 5.0)) AND (tStateTimer.ET > T#120S) THEN
            iState := 40;
        ELSIF (rSilicaSaturationIndex >= rCritical_SSI_Threshold) AND (tStateTimer.ET > T#60S) THEN
            dwAlarmBitmask := dwAlarmBitmask OR 16#00001000; (* Bit 12: Scaling Runaway Trip *)
            iState := 80;
        END_IF;

    60: (* TURBINE TRIP FAST-BYPASS ENGAGED *)
        wDiagnosticStatusWord := 16#0040; (* Status: Turbine Fast Bypass *)
        dwAlarmBitmask := dwAlarmBitmask OR 16#00002000; (* Bit 13: Turbine Expander Trip *)

        (* Slam open isobutane vapor bypass directly to condensers, quench brine extraction *)
        rValveDemand_HPVap_pct := 100.0; (* Full bypass valve open *)
        rValveDemand_LPVap_pct := 100.0;
        rValveDemand_BrineBypass_pct := 100.0; (* Protect ORC heat exchangers from thermal runup *)
        rPumpDemand_AcidDose_lph := 5.0;

        IF NOT bTurbineTripped AND bEnable THEN
            iState := 30; (* Re-pressurize and ramp back up *)
        ELSIF tStateTimer.ET > T#300S THEN
            iState := 0;  (* Cool down to Standby *)
        END_IF;

    70: (* DEGRADED SENSOR FALLBACK (1oo2 / CONSERVATIVE RUNNING) *)
        wDiagnosticStatusWord := 16#0080; (* Status: Degraded Sensor Control *)
        (* Enforce widened safety deadbands and restricted throttle range *)
        rValveDemand_HPVap_pct := LIMIT(10.0, aControl_u[1], 70.0);
        rValveDemand_LPVap_pct := LIMIT(10.0, aControl_u[2], 65.0);
        rValveDemand_BrineBypass_pct := LIMIT(30.0, aControl_u[3] + 15.0, 85.0);
        rPumpDemand_AcidDose_lph := LIMIT(10.0, rCalculatedAcidDemand * 1.30, 130.0);

        IF NOT bDegradedSensorMode THEN
            iState := 40; (* Return to nominal once all TMR channels are cleared *)
        END_IF;

    80: (* EMERGENCY SHUTDOWN BRINE DUMP & SAFE ISOLATION *)
        bSafetyTripActive := TRUE;
        bSystemReady := FALSE;
        wDiagnosticStatusWord := 16#0100; (* Status: Emergency Shutdown Trip *)
        dwAlarmBitmask := dwAlarmBitmask OR 16#00004000; (* Bit 14: Emergency Isolation Tripped *)

        (* Fail-Safe Actuator Topology: Divert 100% brine to reinjection separator dump *)
        rValveDemand_BrineBypass_pct := 100.0;
        rValveDemand_HPVap_pct := 0.0;
        rValveDemand_LPVap_pct := 0.0;
        rPumpDemand_AcidDose_lph := 0.0;

        IF tStateTimer.ET > T#10S THEN
            iState := 90;
        END_IF;

    90: (* TRIP LATCHED: REQUIRING OPERATOR ACKNOWLEDGE *)
        bSafetyTripActive := TRUE;
        bSystemReady := FALSE;
        wDiagnosticStatusWord := 16#0200; (* Status: Trip Latched *)
        rValveDemand_BrineBypass_pct := 100.0;
        rValveDemand_HPVap_pct := 0.0;
        rValveDemand_LPVap_pct := 0.0;
        rPumpDemand_AcidDose_lph := 0.0;

        (* Awaiting bAcknowledgeFault evaluated in Section 1 *)

END_CASE;

(*
========================================================================================================
ALGORITHM SECTION 6: RATE-OF-CHANGE SLEW LIMITING & FINAL HARDWARE CLAMPING
========================================================================================================
*)
rSlewCap := rMaxSlewRate_pct_s * rCycleTime_s;

(* Slew Limiter for HP Vaporizer Valve *)
IF (rValveDemand_HPVap_pct - aControl_u_prev[1]) > rSlewCap THEN
    rValveDemand_HPVap_pct := aControl_u_prev[1] + rSlewCap;
ELSIF (aControl_u_prev[1] - rValveDemand_HPVap_pct) > rSlewCap THEN
    rValveDemand_HPVap_pct := aControl_u_prev[1] - rSlewCap;
END_IF;
rValveDemand_HPVap_pct := LIMIT(0.0, rValveDemand_HPVap_pct, 100.0);
aControl_u_prev[1] := rValveDemand_HPVap_pct;

(* Slew Limiter for LP Vaporizer Valve *)
IF (rValveDemand_LPVap_pct - aControl_u_prev[2]) > rSlewCap THEN
    rValveDemand_LPVap_pct := aControl_u_prev[2] + rSlewCap;
ELSIF (aControl_u_prev[2] - rValveDemand_LPVap_pct) > rSlewCap THEN
    rValveDemand_LPVap_pct := aControl_u_prev[2] - rSlewCap;
END_IF;
rValveDemand_LPVap_pct := LIMIT(0.0, rValveDemand_LPVap_pct, 100.0);
aControl_u_prev[2] := rValveDemand_LPVap_pct;

(* Slew Limiter for Brine Thermal Bypass 3-Way Valve *)
IF (iState <> 80) AND (iState <> 90) THEN
    IF (rValveDemand_BrineBypass_pct - aControl_u_prev[3]) > (rSlewCap * 1.5) THEN
        rValveDemand_BrineBypass_pct := aControl_u_prev[3] + (rSlewCap * 1.5);
    ELSIF (aControl_u_prev[3] - rValveDemand_BrineBypass_pct) > (rSlewCap * 1.5) THEN
        rValveDemand_BrineBypass_pct := aControl_u_prev[3] - (rSlewCap * 1.5);
    END_IF;
END_IF;
rValveDemand_BrineBypass_pct := LIMIT(0.0, rValveDemand_BrineBypass_pct, 100.0);
aControl_u_prev[3] := rValveDemand_BrineBypass_pct;

(* Final Chemical Dosing Clamping *)
rPumpDemand_AcidDose_lph := LIMIT(0.0, rPumpDemand_AcidDose_lph, 150.0);

END_FUNCTION_BLOCK
